'use client'
import { DownloadOutlined, FilePdfOutlined, FileWordOutlined, FileExcelOutlined, FilePptOutlined, FileZipOutlined, FileOutlined, PhoneOutlined } from '@ant-design/icons';
import './styles/documentDetail.css'
import { useState, useMemo, useRef, useEffect } from 'react';
import { useAppContext } from '@/appcontext';
import { checkSignIn, downloadDocument } from '@/constants/client';
import DocumentTopup from './documenttopup';
import { Divider, Image } from 'antd';


const DocumentDetail = ({documentinfo}) =>{
const { appcontext } = useAppContext();
    const [showTopup, setShowTopup] = useState(false);

    const detailImages = useMemo(() => {
        const result = [];
        if (documentinfo.IMAGE_LINK)
            result.push(`${process.env.NEXT_PUBLIC_API_URL}${documentinfo.IMAGE_LINK}`);
        try {
            const arr = JSON.parse(documentinfo.IMAGES || '[]');
            if (Array.isArray(arr))
                arr.forEach(p => result.push(`${process.env.NEXT_PUBLIC_API_URL}${p}`));
        } catch {}
        return result;
    }, [documentinfo.IMAGE_LINK, documentinfo.IMAGES]);

    const thumbnailSrc = documentinfo.IS_FOLDER ? '/folder.png' : '/docTaiLieu.png';

    const [selectedImg, setSelectedImg] = useState(null);
    const [orderedImages, setOrderedImages] = useState([]);
    const [slideOffset, setSlideOffset] = useState(0);
    const [animating, setAnimating] = useState(false);
    const [needsLoop, setNeedsLoop] = useState(false);
    const stripWrapRef = useRef(null);

    const THUMB_W = 80; // 72px + 8px gap

    useEffect(() => {
        setOrderedImages(detailImages);
        setSelectedImg(detailImages[0] ?? null);
    }, [detailImages]);

    useEffect(() => {
        if (!stripWrapRef.current || orderedImages.length === 0) return;
        const containerWidth = stripWrapRef.current.offsetWidth;
        setNeedsLoop(orderedImages.length * THUMB_W > containerWidth);
    }, [orderedImages]);

    const handleSelectImg = (img, idx) => {
        if (animating) return;
        setSelectedImg(img);
        if (!needsLoop || idx === 0) return;
        setAnimating(true);
        setSlideOffset(-(idx * THUMB_W));
        setTimeout(() => {
            setOrderedImages(prev => [...prev.slice(idx), ...prev.slice(0, idx)]);
            setSlideOffset(0);
            setAnimating(false);
        }, 300);
    };

    const fileTypeIcon = (type) => {
        const iconStyle = { fontSize: 32 };
        switch ((type || '').toLowerCase()) {
            case 'doc':
            case 'docx':
                return <FileWordOutlined style={{ ...iconStyle, color: '#2b579a' }} />;
            case 'pdf':
                return <FilePdfOutlined style={{ ...iconStyle, color: '#f40f02' }} />;
            case 'xls':
            case 'xlsx':
                return <FileExcelOutlined style={{ ...iconStyle, color: '#217346' }} />;
            case 'ppt':
            case 'pptx':
                return <FilePptOutlined style={{ ...iconStyle, color: '#d24726' }} />;
            case 'rar':
            case 'zip':
                return <FileZipOutlined style={{ ...iconStyle, color: '#f5a623' }} />;
            default:
                return <FileOutlined style={{ ...iconStyle, color: '#888' }} />;
        }
    };

    const [showPreview, setShowPreview] = useState(false);

    const toggleTopup = () => {
        setShowTopup(!showTopup);
    };

    const buyDocument = async () => {
            if (!appcontext.username) {
                await checkSignIn();
            }
            else {
                setShowTopup(true)
            }
    }

    console.log(documentinfo)

    return (
        <div 
            className="row" 
            style={{backgroundColor:"#ffffff", padding:"30px", borderRadius:"2px", boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px"}}
            >
            <div className="col-md-5 col-lg-5 col-xl-5">
                <div style={{ width: '100%' }}>
                    {(() => {
                        const src = selectedImg || detailImages[0];
                        const wrapperStyle = {
                            width: '100%',
                            aspectRatio: '3/4',
                            border: '1px solid #eee',
                            borderRadius: 4,
                            background: '#fafafa',
                            display: 'flex',
                            justifyContent: 'center',
                            alignItems: 'center',
                            overflow: 'hidden',
                        };
                        return src ? (
                            <div style={wrapperStyle}>
                                <Image src={src} alt="Tài liệu toán.vn" style={{ width: '100%', height: '100%', objectFit: 'contain' }} />
                            </div>
                        ) : (
                            <div style={wrapperStyle}>
                                <img src={thumbnailSrc} alt="Tài liệu toán.vn" style={{ width: 100, height: 100, objectFit: 'contain', opacity: 0.6 }} />
                            </div>
                        );
                    })()}
                    {orderedImages.length > 0 && (
                        <>
                        <div ref={stripWrapRef} style={{ marginTop: 10, overflow: 'hidden' }}>
                            <div
                                style={{
                                    display: 'flex',
                                    gap: 8,
                                    flexWrap: needsLoop ? 'nowrap' : 'wrap',
                                    transform: needsLoop ? `translateX(${slideOffset}px)` : 'none',
                                    transition: animating ? 'transform 0.3s ease' : 'none',
                                }}
                            >
                                {orderedImages.map((img, idx) => (
                                    <Image
                                        key={img}
                                        src={img}
                                        alt={`preview-${idx}`}
                                        onClick={() => handleSelectImg(img, idx)}
                                        style={{
                                            flexShrink: 0,
                                            width: 72,
                                            height: 72,
                                            objectFit: 'cover',
                                            cursor: animating ? 'default' : 'pointer',
                                            borderRadius: 4,
                                            border: selectedImg === img ? '2px solid #1890ff' : '1px solid #ddd',
                                            transition: 'border 0.2s',
                                        }}
                                    />
                                ))}
                            </div>
                        </div>
                        <p style={{ fontStyle: 'italic', fontSize: 14, color: '#888', marginTop: 6, marginBottom: 0, textAlign: 'center' }}>
                            Click vào ảnh để xem chi tiết hơn
                        </p>
                        </>
                    )}
                </div>
            </div>
            <div className="col-md-7 col-lg-7 col-xl-7">
                
                {/* name */}
                <div className='form-name' dangerouslySetInnerHTML={{ __html: documentinfo?.NAME || '' }} />
                
                {/* info download */}
                {/* <div className="form-info-download">
                    <div className='info-download-item'>
                        <DownloadOutlined style={{color:"#5c6c75"}}/>
                        <span>{888} Lượt tải</span>
                    </div>
                </div> */}
                
                {/* price */}
                {documentinfo?.PRICE ? <div className='form-price'>
                    <p>{new Intl.NumberFormat('vi-VN').format(documentinfo.PRICE)} đ</p>
                </div> : null}
                
                {/*  info */}
                <div className="detail-info row" >
                    <div className="col-lg-6">
                        <table className="table table-borderless mb-0">
                            <tbody>
                                <tr>
                                    <td width="100">Lớp:</td>
                                    <td><strong>{documentinfo?.GRADE || 'đang cập nhật'}</strong></td>
                                </tr>
                                <tr>
                                    <td>Môn:</td>
                                    <td><strong>{documentinfo?.SUBJECT || 'đang cập nhật'}</strong></td>
                                </tr>
                                <tr>
                                    <td>Loại:</td>
                                    <td>
                                        <strong>
                                            {documentinfo?.CATEGORY === 'single' ? 'Tài liệu lẻ'
                                                : documentinfo?.CATEGORY === 'bundle' ? 'Tài liệu bộ'
                                                : 'đang cập nhật'}
                                        </strong>
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                    <div className="col-lg-6">
                        <table className="table table-borderless mb-0">
                            <tbody>
                                <tr>
                                    <td width="100">File:</td>
                                    <td>
                                        {documentinfo?.FILE_TYPE
                                            ? fileTypeIcon(documentinfo.FILE_TYPE)
                                            : <span>đang cập nhật</span>}
                                    </td>
                                </tr>
                                <tr>
                                    <td>Số trang:</td>
                                    <td>
                                        <strong>{documentinfo?.PAGE_COUNT ? `${documentinfo.PAGE_COUNT} trang` : 'đang cập nhật'}</strong>
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>

                {/*  Action */}
                <div className="form-action">
                    {!documentinfo.BOUGHT && documentinfo.LINK_FULL
                        ? <button type="button" className="btn btn-dark rounded-0 me-2 mb-2 mt-2" onClick={() => {
                              if (documentinfo.LINK_PREVIEW) {
                                  setShowPreview(true);
                              } else {
                                  window.open(documentinfo.LINK_FULL);
                              }
                          }}>
                              <FilePdfOutlined style={{marginRight:"10px"}}/> XEM THỬ
                          </button>
                        : null}
                    
                    <button
                        className="btn btn-success rounded-0 mb-2 mt-2" type="button" data-bs-toggle="modal" data-bs-target="#buyDocumentModal"
                        onClick={()=>documentinfo?.BOUGHT ? downloadDocument(documentinfo) : buyDocument()}
                    >
                        {documentinfo?.BOUGHT ?<><DownloadOutlined style={{marginRight:"10px"}}/> TẢI LẠI</> : <><DownloadOutlined style={{marginRight:"10px"}}/> TẢI XUỐNG</>}
                    </button>
                </div>
                <Divider/>

                {/* buy step */}
                <div className="alert alert-info rounded-0" role="alert">
                    MUA NGAY ĐỂ XEM TOÀN BỘ TÀI LIỆU
                </div>
                <div className="order-step">
                    <h6 style={{
                        color:"#008000"
                    }}>CÁCH TẢI TÀI LIỆU:</h6>
                    <ul className="ps-4">
                        <li className="mb-1"><strong>Bước 1:</strong> Nếu số dư tài khoản đủ, bạn chỉ cần ấn nút <strong>TẢI XUỐNG</strong>.</li>
                        <li className="mb-1"><strong>Bước 2:</strong> Nếu số dư không đủ, ấn TẢI XUỐNG để mở bảng chọn <strong>Nạp tiền</strong>. Sau đó chọn số tiền muốn nạp và quét mã QR để thanh toán.</li>
                        <li className="mb-1"><strong>Bước 3:</strong> Sau khi thanh toán thành công, vui lòng chụp lại giao dịch rồi gửi đến số Zalo <a href="https://zalo.me/0386117490" target="_blank" rel="noreferrer"><strong>0386.117.490</strong> <span>(nhấn vào đây)</span></a> để được xác nhận.</li>
                        <li className="mb-1"><strong>Bước 4:</strong> Sau khi được xác nhận thành công, quay lại trang này và tải tài liệu.</li>
                    </ul>
                    <p className="mt-2 ms-3"
                        style={{
                        fontSize:"16px"
                    }}>
                        <a className="btn btn-info btn-sm rounded-0"
                            style={{
                                color:"#fff",
                                fontSize:"16px",
                                padding:"3px 7px"
                            }}
                            href="https://zalo.me/0386117490"
                            target="_blank"
                            rel="noreferrer"
                        >
                            Tư vấn nhanh
                        </a>
                        <PhoneOutlined style={{ margin:"0 8px" }}/>
                        <span className="d-none d-md-inline">Hotline hỗ trợ:</span>
                        <span className="fs-5" style={{color:"#FF5722"}}> 0386.117.490 </span>
                    </p>
                </div>
                <Divider/>

                {/* description */}
                <div >
                    <div dangerouslySetInnerHTML={{ __html: documentinfo.DESCRIPTION }} />
                </div>

            </div>
            {/* MOdal */}
            {showTopup && <DocumentTopup props={{ onClose: toggleTopup, documentinfo }} />}

            {showPreview && (
                <div
                    onClick={() => setShowPreview(false)}
                    style={{
                        position: 'fixed', inset: 0,
                        background: 'rgba(0,0,0,0.75)',
                        zIndex: 9999,
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                    }}
                >
                    <div
                        onClick={e => e.stopPropagation()}
                        style={{
                            background: '#fff', borderRadius: 8,
                            width: '90vw', height: '90vh',
                            display: 'flex', flexDirection: 'column',
                            overflow: 'hidden',
                        }}
                    >
                        <div style={{
                            display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                            padding: '10px 16px', borderBottom: '1px solid #eee', flexShrink: 0,
                        }}>
                            <span style={{ fontWeight: 600, fontSize: 15 }}>
                                <FilePdfOutlined style={{ color: '#f40f02', marginRight: 8 }} />
                                Xem thử tài liệu
                            </span>
                            <button type="button" className="btn-close" onClick={() => setShowPreview(false)} />
                        </div>
                        <iframe
                            src={documentinfo.LINK_PREVIEW}
                            title="Xem thử tài liệu"
                            style={{ flex: 1, border: 'none', width: '100%' }}
                        />
                    </div>
                </div>
            )}
        </div>
    )
}

export default DocumentDetail